INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('f8ecdf7a-f84e-5026-9756-ef9f74c62e6e', 'Sit-to-Stand', 'Camera: side view, whole body in frame. Sit on a firm chair with feet flat and hip-width apart. Lean slightly forward and stand up fully without using your hands, then sit back down slowly. Safety: keep a stable chair against a wall; stop if you feel dizzy or knee pain.', 'BOTH_LEGS', 'LOW', 10, 90, 'sit_to_stand') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('4ceb12e3-b3be-5dd2-afcc-95437849bf9c', 'Shoulder Abduction', 'Camera: facing you, whole body in frame. Stand tall with arms by your sides. Raise both arms out to the side up to shoulder height with elbows straight, hold for one second, and lower slowly. Safety: do not raise above a pain-free range.', 'BOTH_ARMS', 'LOW', 10, 60, 'shoulder_abduction') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('2946137f-7a3a-5796-88da-ded8a02c3fcb', 'Shoulder Flexion', 'Camera: side view, whole body in frame. Stand with arms by your sides. Raise both arms forward and up to shoulder height with elbows straight and thumbs up, hold for one second, and lower slowly. Safety: do not arch the back.', 'BOTH_ARMS', 'LOW', 10, 60, 'shoulder_flexion') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('c70f199d-e077-5a20-bdd9-2423b7a85fe9', 'Standing Hip Abduction', 'Camera: facing you, whole body in frame. Stand beside a chair and hold it for support. Lift one leg out to the side keeping the toes forward and the body upright, then lower it. Repeat on the other side. Safety: do not lean the trunk.', 'BOTH_LEGS', 'LOW', 10, 90, 'hip_abduction') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('aa576b35-c58d-5790-a9fc-a9e5056e15f4', 'Seated Knee Extension', 'Camera: side view, whole body in frame. Sit upright on a chair. Straighten one knee until the leg is level with the hip, hold for two seconds, and lower slowly. Alternate legs. Safety: keep the back against the chair.', 'BOTH_LEGS', 'LOW', 12, 90, 'knee_extension') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('3e402332-78f9-5011-a38e-0d193ed56b15', 'Elbow Flexion', 'Camera: side view, whole body in frame. Stand or sit with arms by your sides, palms forward. Bend the elbows to bring the hands toward the shoulders, keeping the upper arms still against your body, then lower slowly. Use a light bottle of water if comfortable.', 'BOTH_ARMS', 'LOW', 12, 60, 'elbow_flexion') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('1dc9d0e9-db44-5432-b1d1-7ac70680fe06', 'Wall Push-Up', 'Camera: side view, whole body in frame, wall at one edge of the picture. Stand an arm''s length from a wall with palms on the wall at shoulder height. Bend the elbows to bring the chest toward the wall, then push back. Safety: keep the body straight from head to heels.', 'BOTH_ARMS', 'MODERATE', 10, 90, 'wall_push_up') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('5dc92b58-acf9-5714-9098-ceae5de18c9d', 'Heel Raise', 'Camera: side view, whole body in frame. Stand behind a chair holding the back of it. Rise onto your toes, hold for one second, and lower slowly. Safety: keep holding the chair throughout.', 'BOTH_LEGS', 'LOW', 12, 60, 'heel_raise') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('de7a6671-c3bb-59c8-86d2-0f30c2da6983', 'Mini Squat', 'Camera: side view, whole body in frame. Stand with feet shoulder-width apart holding a support. Bend the knees about 30 degrees keeping the heels down and the chest up, then stand up. Safety: knees must not pass the toes.', 'BOTH_LEGS', 'MODERATE', 10, 90, 'mini_squat') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('d72fb12f-7ec9-54df-8ae3-c812f6af59cb', 'Seated Marching', 'Camera: side view, whole body in frame. Sit upright on a chair without leaning back. Lift one knee toward the chest, lower it, and alternate legs at a steady pace.', 'BOTH_LEGS', 'LOW', 20, 90, 'seated_marching') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('851a661b-6068-5a20-8521-d9648cfc7003', 'Glute Bridge', 'Camera: side view, phone on the floor about 2 m away, whole body in frame. Lie on your back on a mat with knees bent and feet flat. Squeeze the buttocks and lift the hips until shoulders, hips and knees are in a straight line, then lower slowly. Safety: do not arch the lower back.', 'CORE', 'MODERATE', 10, 90, 'glute_bridge') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('e3b87b69-7059-590d-8977-8011373bcc2f', 'Tandem Stance', 'Camera: facing you, whole body in frame. Stand next to a counter. Place one foot directly in front of the other, heel touching toe, and hold for 30 seconds. Switch feet. Safety: always keep one hand near the support.', 'BOTH_LEGS', 'LOW', 4, 120, 'tandem_stance') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('b56023cf-6125-5e6d-abc8-732551a61b2a', 'Bird Dog', 'Camera: side view, phone on the floor about 2 m away, whole body in frame. Kneel on a mat on hands and knees, hands under shoulders, knees under hips. Stretch one arm forward and the opposite leg back until both are level with your back, hold for two seconds, return, and switch sides. Safety: keep the back flat, do not twist.', 'CORE', 'LOW', 10, 90, 'bird_dog') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('d0356cfa-b1a9-5ad1-9c35-c6cc923f7d4d', 'Step-Up', 'Camera: side view, whole body and the step in frame. Stand facing a low step holding a rail. Step up with one foot, straighten that leg fully, bring the other foot up, then step down slowly. Alternate the leading leg. Safety: use a step no higher than 15 cm.', 'BOTH_LEGS', 'MODERATE', 10, 120, 'step_up') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
INSERT INTO exercise (exercise_id, exercise_name, instruction_text, target_body_area, intensity_level, default_repetitions, default_duration_sec, pose_key) VALUES ('568364bd-7b20-58d0-af1e-ccd3fdb47165', 'March in Place', 'Camera: side view, whole body in frame. Stand tall and march on the spot, lifting the knees to hip height if comfortable and swinging the arms, at a steady pace.', 'FULL_BODY', 'MODERATE', 30, 120, 'march_in_place') ON CONFLICT (exercise_id) DO UPDATE SET exercise_name = excluded.exercise_name, instruction_text = excluded.instruction_text, target_body_area = excluded.target_body_area, intensity_level = excluded.intensity_level, default_repetitions = excluded.default_repetitions, default_duration_sec = excluded.default_duration_sec, pose_key = excluded.pose_key;
